from pathlib import Path
import json,sys
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT/'_BUILD_SOURCE'))
import shoot
OUT=ROOT/'_shots/overdrive_frontend_overhaul_1013';OUT.mkdir(parents=True,exist_ok=True)
checks=[];errors=[]
def check(name,value):
 checks.append({'name':name,'passed':bool(value)});print(('PASS ' if value else 'FAIL ')+name,flush=True)
port,stop=shoot.serve(str(ROOT))
try:
 with sync_playwright() as pw:
  browser=pw.chromium.launch();page=browser.new_page(viewport={'width':1280,'height':1000})
  page.on('pageerror',lambda e:errors.append(str(e)));page.on('console',lambda m:errors.append(m.text) if m.type=='error' else None)
  page.on('response',lambda r:errors.append(f'HTTP {r.status} {r.url}') if r.status>=400 else None)
  page.add_init_script("window.testPad={id:'Password pin QA',index:0,connected:true,mapping:'standard',axes:[0,0,0,0],buttons:Array.from({length:24},()=>({pressed:false,value:0}))};Object.defineProperty(navigator,'getGamepads',{value:()=>[testPad]});")
  page.goto(f'http://127.0.0.1:{port}/expansion/topdown/index.html?fullscreen=0',wait_until='domcontentloaded',timeout=90000)
  page.wait_for_function('window.TDGAME&&TDGAME.G.state==="boot"',timeout=90000);page.evaluate('TDGAME.freeze()')
  page.wait_for_function('TD.FRONT_WARM.every(k=>!!ART.get(k))',timeout=60000)
  def frames(n=20):page.evaluate('n=>TDGAME.step(n)',n)
  def tap(k):page.keyboard.down(k);frames(1);page.keyboard.up(k);frames()
  def go():page.evaluate("TD.Frontend.pending=null;TD.Frontend.returnTo='title';TD.Frontend.go('password')");frames()
  def click(kind,i=None):
   q=page.evaluate("([kind,i])=>TD.Frontend.rects.find(r=>r.kind===kind&&(i===null||r.i===i))",[kind,i])
   b=page.locator('#screen').bounding_box();v=page.evaluate('TD.Display');page.mouse.move(b['x']+(q['x']+q['w']/2)*b['width']/v['w'],b['y']+(q['y']+q['h']/2)*b['height']/v['h']);page.mouse.down();frames(1);page.mouse.up();frames()
  def pad(i):page.evaluate('i=>{testPad.buttons[i].pressed=true;testPad.buttons[i].value=1}',i);frames(1);page.evaluate('i=>{testPad.buttons[i].pressed=false;testPad.buttons[i].value=0}',i);frames()
  frames();tap('Enter');tap('Enter');tap('ArrowDown');tap('Enter')
  check('title Password opens the pinned menu through actual inputs',page.evaluate('TDGAME.G.state==="password"&&TD.Frontend.pwSel===0'))
  pins=page.evaluate('TD.Frontend.pinnedPasswords()');print(json.dumps(pins),flush=True)
  check('all six playable levels have visible pins and valid Yuri Normal Hotwire passwords',page.evaluate("TD.Frontend.pinnedPasswords().map(p=>p.id).join(',')==='2,3,4,5,6,7'&&TD.Frontend.pinnedPasswords().every(p=>{const d=TD.Password.decode(p.code);return d.sel===p.sel&&d.pilot==='yuri'&&d.difficulty==='normal'&&d.companion==='hotwire';})"))
  page.evaluate('TDGAME.render()');page.locator('#screen').screenshot(path=str(OUT/'password_menu.png'))
  check('pin buttons and manual keypad all fit within the screen without overlapping',page.evaluate("(()=>{const r=TD.Frontend.rects;return r.length===46&&r.every(a=>a.x>=0&&a.y>=0&&a.x+a.w<=640&&a.y+a.h<475)&&r.every((a,i)=>r.slice(i+1).every(b=>a.x+a.w<=b.x||b.x+b.w<=a.x||a.y+a.h<=b.y||b.y+b.h<=a.y));})()"))
  for i,p in enumerate(pins):
   go();click('pin',i);check(f'clicking Level {p["id"]} loads its password and pilot screen',page.evaluate("sel=>TDGAME.G.state==='pilot'&&TDGAME.G.sel===sel&&TD.pilot==='yuri'&&TD.difficulty==='normal'&&TD.companion==='hotwire'",p['sel']))
   tap('Enter');check(f'confirming Level {p["id"]} reaches the matching briefing',page.evaluate("id=>TDGAME.G.state==='brief'&&TDGAME.G.mission===id",p['id']))
  go();pad(12);check('controller up wraps from first pin to last',page.evaluate('TD.Frontend.pwSel===5'))
  pad(13);check('controller down wraps back to first pin',page.evaluate('TD.Frontend.pwSel===0'))
  pad(15);check('controller right enters the manual keypad',page.evaluate('TD.Frontend.pwSel===6'))
  pad(0);check('controller A can still enter a manual character',page.evaluate("TD.Frontend.pw==='OD-A'"))
  pad(14);pad(13);pad(0);check('controller A selects the fortress pin',page.evaluate('TDGAME.G.state==="pilot"&&TDGAME.G.sel===1'))
  go();click('key',45);frames(1);check('TYPE still opens manual keyboard entry',page.evaluate('TD.Frontend.typing&&!!TD.Input.textSink'))
  page.keyboard.type('237E-5JXQ');frames(1);tap('Backspace');check('Backspace deletes a typed character without leaving the menu',page.evaluate("TD.Frontend.pw==='OD-237E-5JX'&&TDGAME.G.state==='password'"))
  page.keyboard.type('Q');frames(1);click('load');check('manual typed password loads Night Run',page.evaluate('TDGAME.G.state==="pilot"&&TDGAME.G.sel===4'))
  go();page.evaluate("TD.Frontend.pw='OD-2222-2222'");click('load');check('invalid manual passwords retain their error feedback',page.evaluate('TDGAME.G.state==="password"&&TD.Frontend.message.includes("INVALID")'))
  page.evaluate("TD.Frontend.pw=TD.Password.encode(1,'yuri','insanity','hotwire')");click('load');check('Insanity manual codes retain the existing unlock gate',page.evaluate('TDGAME.G.state==="password"&&TD.Frontend.message.includes("UNLOCK INSANITY")'))
  go();tap('b');check('B returns from pinned passwords to title',page.evaluate('TDGAME.G.state==="title"'))
  go();pad(12);pad(15);check('last pin reaches the bottom manual-keypad row',page.evaluate('TD.Frontend.pwSel===38'))
  pad(14);check('left from bottom keypad row returns to the Level 7 pin',page.evaluate('TD.Frontend.pwSel===5'))
  pad(0);check('controller confirms Prism Bastion from the last pin',page.evaluate('TDGAME.G.state==="pilot"&&TDGAME.G.sel===5'))
  check('desert and Prism Bastion replace old menu descriptions',page.evaluate("TD.Frontend.pinnedPasswords().find(p=>p.id===5).name==='DESERT BREAKER'&&TD.Frontend.pinnedPasswords().find(p=>p.id===7).name==='PRISM BASTION'&&!TD.Frontend.pinnedPasswords().some(p=>/MUSEUM/i.test(p.name))"))
  page.evaluate("TD.Frontend.pending=null;TD.Frontend.returnTo='title';TD.Input.setPadStyle('standard');TD.Frontend.go('help');TD.Frontend.helpTab=2");frames()
  page.evaluate("window.helpCopy=[];const front=TD.Frontend,tx=front.tx;front.tx=function(s,...a){helpCopy.push(String(s));return tx.call(this,s,...a)};TDGAME.render();front.tx=tx;0")
  check('on-foot Help explicitly teaches F toggle, controller toggle, crawl and stand recovery',page.evaluate("helpCopy.some(t=>t.includes('TAP F OR MODE + X'))&&helpCopy.some(t=>t.includes('TAP AGAIN TO STAND'))&&helpCopy.join(' ').includes('PRONE TO CRAWL')"))
  check('cover Help describes peek and blindfire controls without weapon swaps',page.evaluate("helpCopy.some(t=>t.includes('FIRE IN COVER: PEEK'))&&helpCopy.some(t=>t.includes('RETINA + FIRE: BLINDFIRE'))&&!helpCopy.some(t=>/SLOT|CYCLE WEAPON/.test(t))"))
  page.locator('#screen').screenshot(path=str(OUT/'help_foot.png'))
  tap('ArrowRight');check('Help advances to the pseudo-3D base control page',page.evaluate('TD.Frontend.helpTab===3'))
  page.evaluate("helpCopy=[];const front=TD.Frontend,tx=front.tx;front.tx=function(s,...a){helpCopy.push(String(s));return tx.call(this,s,...a)};TDGAME.render();front.tx=tx;0")
  check('base Help describes sidestep, duck and Retina reticle aiming',page.evaluate("helpCopy.includes('LEFT / RIGHT: SIDESTEP')&&helpCopy.includes('DOWN OR HOLD L: DUCK')&&helpCopy.includes('HOLD R: STAND + FREE AIM')&&helpCopy.includes('D-PAD MOVES FREE-AIM RETICLE')&&helpCopy.includes('NO JUMP / STAY BEHIND COVER')"))
  page.locator('#screen').screenshot(path=str(OUT/'help_base.png'))
  page.evaluate("TD.Input.setPadStyle('six');helpCopy=[];const front=TD.Frontend,tx=front.tx;front.tx=function(s,...a){helpCopy.push(String(s));return tx.call(this,s,...a)};TDGAME.render();front.tx=tx;0")
  check('Genesis base Help names C or Mode cover, Z free-aim and X duck',page.evaluate("helpCopy.includes('DOWN / C / MODE: DUCK')&&helpCopy.includes('HOLD Z: STAND + FREE AIM')&&helpCopy.includes('X OR MODE + X: TOGGLE DUCK')"))
  page.locator('#screen').screenshot(path=str(OUT/'help_base_six.png'))
  page.evaluate("TD.Frontend.helpTab=2;helpCopy=[];const front=TD.Frontend,tx=front.tx;front.tx=function(s,...a){helpCopy.push(String(s));return tx.call(this,s,...a)};TDGAME.render();front.tx=tx;0")
  check('Genesis infantry Help names Mode cover and Mode Z blindfire',page.evaluate("helpCopy.includes('HOLD MODE: COVER')&&helpCopy.includes('MODE + Z: BLINDFIRE')"))
  page.locator('#screen').screenshot(path=str(OUT/'help_foot_six.png'))
  page.evaluate("TD.Input.setPadStyle('standard');TD.Frontend.helpTab=3")
  tap('ArrowRight');check('four Help pages wrap back to six-button controls',page.evaluate('TD.Frontend.helpTab===0'))
  page.evaluate("TDGAME.G.mission=7;TD.Frontend.returnTo='pause';TD.Frontend.go('help')");frames()
  check('pausing Level 7 opens its relevant Help page automatically',page.evaluate('TD.Frontend.helpTab===3'))
  award=page.evaluate("(()=>{const a=TD.Achievements,old=a.data,queue=a.queue; a.data={unlocked:{},clears:{2:true,3:true,4:true,5:true},difficultyClears:{furious:{2:true,3:true,4:true,5:true}}};a.queue=[];const pilot=TD.pilot,diff=TD.difficulty;TD.pilot='yuri';TD.difficulty='furious';a.finish({mission:6,deaths:0});const premature=!!a.data.unlocked.campaign||!!a.data.unlocked.furious;a.finish({mission:7,deaths:0});const awarded=!!a.data.unlocked.campaign&&!!a.data.unlocked.furious;a.data=old;a.queue=queue;TD.pilot=pilot;TD.difficulty=diff;localStorage.setItem('bof_od_achievements',JSON.stringify(old));return{premature,awarded}})()")
  check('campaign rewards require the new final level and then unlock',not award['premature'] and award['awarded'])
  go();page.set_viewport_size({'width':520,'height':650});frames();page.evaluate('TDGAME.render()');page.locator('#screen').screenshot(path=str(OUT/'password_menu_narrow.png'))
  check('password pins fit a narrow browser pane',page.evaluate('(()=>{const r=document.getElementById("screen").getBoundingClientRect();return r.left>=0&&r.right<=innerWidth+1&&r.bottom<=innerHeight+1;})()'))
  check('no page console or missing-asset errors',not errors)
  (OUT/'report.json').write_text(json.dumps({'pins':pins,'checks':checks,'errors':errors},indent=2)+'\n',encoding='utf-8');browser.close()
finally:stop()
print(f'{sum(c["passed"] for c in checks)}/{len(checks)} checks passed');sys.exit(0 if all(c['passed'] for c in checks) else 1)
